list_blogs.code:
use WebCommander\Sdk\Resources\Blogs\Blogs;

$response = Blogs::listBlogs($client, ['visibility' => 'open', 'limit' => 20]);

foreach ($response->map['blogs'] as $blog) {
    echo $blog['id'], ' ', $blog['title'], ' (', $blog['date'], ')', PHP_EOL;
}
echo $response->map['pagination']['total'], ' blog posts in total', PHP_EOL;

create_blog.code:
use WebCommander\Sdk\Resources\Blogs\Blogs;

$response = Blogs::createBlog($client, [
    'blog' => [
        'title' => 'Spring Sale Announcement', 'content' => '<p>Save up to 40% on selected products until the end of the month.</p>',
        'date' => '2026-09-28', 'is_published' => true, 'visibility' => 'open', 'categories' => [['id' => 31]],
        'image' => ['file_name' => 'spring-cover.png', 'base64' => 'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNk+M9QDwADhgGAWjR9awAAAABJRU5ErkJggg==', 'title' => 'Spring sale cover', 'alternative_text' => 'Spring sale banner'],
        'seo_configs' => ['meta_tag' => [['name' => 'description', 'value' => 'Spring sale: up to 40% off']]],
    ],
]);

echo $response->map['blog']['id'], PHP_EOL;

get_blog.code:
use WebCommander\Sdk\Resources\Blogs\Blogs;

$response = Blogs::getBlog($client, 1201);

$blog = $response->map['blog'];
echo $blog['title'], ' (', $blog['url'], ')', PHP_EOL;
echo $blog['visibility'], ', ', $blog['is_published'] ? 'published' : 'not published', PHP_EOL;

update_blog.code:
use WebCommander\Sdk\Resources\Blogs\Blogs;

$response = Blogs::updateBlog($client, 1201, [
    'blog' => [
        'title' => 'Spring Sale Extended', 'content' => '<p>The spring sale now runs one more week.</p>', 'date' => '2026-09-28',
        'is_published' => true, 'visibility' => 'restricted', 'visible_to' => 'selected', 'categories' => [['id' => 31]],
        'seo_configs' => ['meta_tag' => [['name' => 'description', 'value' => 'Spring sale: up to 40% off']]],
        'selected_customers' => ['customers' => [5501], 'groups' => []],
    ],
]);

echo $response->map['blog']['title'], ' (', $response->map['blog']['visibility'], ')', PHP_EOL;

patch_blog.code:
use WebCommander\Sdk\Resources\Blogs\Blogs;

$response = Blogs::patchBlog($client, 1201, ['blog' => ['title' => 'Spring Sale: Final Week']]);

$blog = $response->map['blog'];
echo $blog['title'], ' (', $blog['url'], ')', PHP_EOL;

list_blog_comments.code:
use WebCommander\Sdk\Resources\Blogs\Blogs;

$response = Blogs::listBlogComments($client, 1201);

foreach ($response->map['comments'] as $comment) {
    echo $comment['id'], ' ', $comment['status'], ': ', $comment['content'], PHP_EOL;
}

create_blog_comment.code:
use WebCommander\Sdk\Resources\Blogs\Blogs;

$response = Blogs::createBlogComment($client, 1201, [
